#!/usr/bin/env bash
#
# Nightly logical backup of the coop-whatsapp Postgres database.
# Installed to /usr/local/bin/coop-backup.sh by deploy/bootstrap.sh and run from
# /etc/cron.d/coop-whatsapp-backup. Keeps 14 daily dumps.
#
#   sudo /usr/local/bin/coop-backup.sh
#
# Encryption: set BACKUP_ENCRYPTION_KEY (generated by bootstrap.sh) and dumps are
# written as coop-YYYY-MM-DD.dump.enc via AES-256-CBC (PBKDF2, 200k iterations).
# In production (NODE_ENV=production) or when REQUIRE_ENCRYPTED_BACKUPS=1 is set,
# the script refuses to write an unencrypted dump at all.
#
# Restore: see "Backups & restore" in DEPLOY.md.

set -euo pipefail

APP_DIR="${APP_DIR:-/opt/coop-whatsapp}"
BACKUP_DIR="${BACKUP_DIR:-/var/backups/coop-whatsapp}"
RETENTION_DAYS="${RETENTION_DAYS:-14}"

cd "$APP_DIR"

read_env() {
  local key="$1" fallback="$2" value
  value="$(grep -E "^${key}=" .env | head -n1 | cut -d= -f2- || true)"
  printf '%s' "${value:-$fallback}"
}

PG_USER="$(read_env POSTGRES_USER coop)"
PG_DB="$(read_env POSTGRES_DB coop)"
ENCRYPTION_KEY="$(read_env BACKUP_ENCRYPTION_KEY '')"
REQUIRE_ENCRYPTED="$(read_env REQUIRE_ENCRYPTED_BACKUPS '')"

install -d -m 700 "$BACKUP_DIR"
STAMP="$(date +%F)"
BASE="$BACKUP_DIR/coop-$STAMP.dump"

# Fail closed: plaintext dumps of member data are never acceptable in prod.
if [ -z "$ENCRYPTION_KEY" ] && { [ "$REQUIRE_ENCRYPTED" = "1" ] || [ "${NODE_ENV:-}" = "production" ]; }; then
  echo "[backup] refusing to write an unencrypted dump: set BACKUP_ENCRYPTION_KEY" >&2
  exit 1
fi

# -Fc = custom format (pg_restore-able, compressed). Written via a temp file so a
# failed dump never looks like a valid backup.
docker compose exec -T postgres pg_dump -U "$PG_USER" -d "$PG_DB" -Fc >"$BASE.tmp"

if [ -n "$ENCRYPTION_KEY" ]; then
  export BACKUP_ENCRYPTION_KEY="$ENCRYPTION_KEY"
  openssl enc -aes-256-cbc -pbkdf2 -iter 200000 -salt \
    -pass env:BACKUP_ENCRYPTION_KEY \
    -in "$BASE.tmp" -out "$BASE.enc.tmp"
  mv "$BASE.enc.tmp" "$BASE.enc"
  chmod 600 "$BASE.enc"
  rm -f "$BASE.tmp"
  echo "[backup] wrote $BASE.enc (encrypted)"
else
  mv "$BASE.tmp" "$BASE"
  chmod 600 "$BASE"
  echo "[backup] wrote $BASE (PLAINTEXT - set BACKUP_ENCRYPTION_KEY to encrypt)" >&2
fi

find "$BACKUP_DIR" -name 'coop-*.dump*' -mtime +"$RETENTION_DAYS" -delete
